/// `s`, percent-encoded as one path segment.
fn segment(s: &str) -> String {
	s.bytes()
		.map(|b| match b {
			b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => (b as char).to_string(),
			b => format!("%{b:02X}"),
		})
		.collect()
}

